def get(self, key, default=None):
    """Return the value for `key`, or `default` when the key is absent."""
    try:
        return from_snapshot(self._lookup(key))
    except KeyError:
        return default

def __call__(self, *args, **kwargs):
    """Invokes the wrapped callable with unwrapped positional and keyword arguments. Returns the finalized result, preserving asynchronous behavior when the wrapped callable returns a coroutine."""
    args = tuple(unwrap(arg) for arg in args)
    kwargs = {key: unwrap(value) for key, value in kwargs.items()}
    result = self._td_real(*args, **kwargs)
    if inspect.isawaitable(result):
        return self._finish_async(result, args, kwargs)
    return self._finish(result, args, kwargs, is_async=False)

def __getattr__(self, name):
    """Resolve a recorded method, nested container, or snapshot attribute."""
    container = self._player.containers.get(self._path, {})
    if name in container:
        return TapeCallable(self._player, self._path, name, container[name])

    path = f"{self._path}.{name}"
    if self._player._has_prefix(path):
        snapshot = None
        if isinstance(self._snapshot, dict):
            snapshot = self._snapshot.get(name)
        return TapeObject(self._player, path, snapshot=snapshot)

    if self._snapshot is not None:
        try:
            return getattr(from_snapshot(self._snapshot), name)
        except AttributeError:
            pass

    raise ResolutionError(f"No recorded attribute {name!r} at {self._path!r}")

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
    """Pure comparison: replayed calls must match the recorded ones in order."""

    def normalise_value(value: Any) -> Any:
        if isinstance(value, dict):
            return {str(key): normalise_value(item) for key, item in sorted(value.items())}
        if isinstance(value, (list, tuple)):
            return [normalise_value(item) for item in value]
        if isinstance(value, set):
            return sorted(normalise_value(item) for item in value)
        return value

    def relative_path(path: Any) -> Any:
        if not isinstance(path, str):
            return path
        if path == client_path:
            return ""
        prefix = f"{client_path}."
        if path.startswith(prefix):
            return path[len(prefix) :]
        return path

    def signature(call: Any) -> Any:
        if not isinstance(call, dict):
            return normalise_value(call)

        path = next(
            (
                call[key]
                for key in ("path", "method", "call", "target", "name", "event")
                if key in call
            ),
            None,
        )
        args = next(
            (
                call[key]
                for key in ("args", "arguments", "params", "positional_args")
                if key in call
            ),
            [],
        )
        kwargs = next(
            (
                call[key]
                for key in ("kwargs", "keyword_args", "keywords")
                if key in call
            ),
            {},
        )

        if path is not None:
            return {
                "path": relative_path(path),
                "args": normalise_value(args),
                "kwargs": normalise_value(kwargs),
            }

        ignored = {
            "dir",
            "source",
            "timestamp",
            "time",
            "sequence",
            "index",
            "return",
            "return_value",
            "result",
            "exception",
        }
        return normalise_value({key: value for key, value in call.items() if key not in ignored})

    expected = [signature(call) for call in recorded_out]
    actual = [signature(call) for call in transcript]
    problems: List[str] = []

    for index, (wanted, got) in enumerate(zip(expected, actual)):
        if wanted != got:
            problems.append(
                f"call mismatch at index {index}: expected "
                f"{json.dumps(wanted, sort_keys=True, default=str)}; got "
                f"{json.dumps(got, sort_keys=True, default=str)}"
            )

    for index in range(len(actual), len(expected)):
        problems.append(
            f"missing replayed call at index {index}: "
            f"{json.dumps(expected[index], sort_keys=True, default=str)}"
        )

    for index in range(len(expected), len(actual)):
        problems.append(
            f"unexpected replayed call at index {index}: "
            f"{json.dumps(actual[index], sort_keys=True, default=str)}"
        )

    return problems

def diff_transcript(recorded_out: List[dict], transcript: List[dict], client_path: str) -> List[str]:
    """Pure comparison: replayed calls must match the recorded ones in order."""

    def call_path(call: Any) -> Any:
        if not isinstance(call, dict):
            return None
        for key in ("path", "method", "call", "target", "name"):
            if key in call:
                return call[key]
        return None

    def is_client_call(call: Any) -> bool:
        path = call_path(call)
        return isinstance(path, str) and (
            path == client_path or path.startswith(f"{client_path}.")
        )

    def normalise(value: Any) -> Any:
        if isinstance(value, dict):
            return {str(key): normalise(item) for key, item in sorted(value.items(), key=lambda item: str(item[0]))}
        if isinstance(value, (list, tuple)):
            return [normalise(item) for item in value]
        if isinstance(value, set):
            return sorted((normalise(item) for item in value), key=repr)
        return value

    def signature(call: Any) -> Any:
        if not isinstance(call, dict):
            return normalise(call)

        path = call_path(call)
        if isinstance(path, str):
            if path == client_path:
                path = ""
            elif path.startswith(f"{client_path}."):
                path = path[len(client_path) + 1 :]

        args = next(
            (
                call[key]
                for key in ("args", "arguments", "params", "positional_args")
                if key in call
            ),
            [],
        )
        kwargs = next(
            (
                call[key]
                for key in ("kwargs", "keyword_args", "keywords")
                if key in call
            ),
            {},
        )
        return {
            "path": path,
            "args": normalise(args),
            "kwargs": normalise(kwargs),
        }

    expected = [signature(call) for call in recorded_out if is_client_call(call)]
    actual = [signature(call) for call in transcript]
    problems: List[str] = []

    for index, (wanted, got) in enumerate(zip(expected, actual)):
        if wanted != got:
            problems.append(
                f"call mismatch at index {index}: expected "
                f"{json.dumps(wanted, sort_keys=True, default=str)}; got "
                f"{json.dumps(got, sort_keys=True, default=str)}"
            )

    for index in range(len(actual), len(expected)):
        problems.append(
            f"missing replayed call at index {index}: "
            f"{json.dumps(expected[index], sort_keys=True, default=str)}"
        )

    for index in range(len(expected), len(actual)):
        problems.append(
            f"unexpected replayed call at index {index}: "
            f"{json.dumps(actual[index], sort_keys=True, default=str)}"
        )

    return problems

def __getattr__(self, name):
    """Delegate public module attributes through recording proxies."""
    value = getattr(self._td_real, name)
    if name.startswith("_"):
        return value
    if isinstance(value, types.ModuleType):
        return ModuleProxy(value, self._rec, self._red)
    if inspect.isclass(value):
        return ClassProxy(value, self._rec, self._red, self._td_real.__name__)
    if callable(value):
        return CallableWrapper(value, self._rec, self._red, self._td_real.__name__, name)
    return value

def diff_tapes(old: dict, new: dict) -> List[str]:
    """Pure drift report: how the newly captured behaviour differs from the old
    tape. Empty list = the recording is still true."""
    problems: List[str] = []

    old_modules = old.get("mocked_modules", {})
    new_modules = new.get("mocked_modules", {})
    if not isinstance(old_modules, dict):
        old_modules = {}
    if not isinstance(new_modules, dict):
        new_modules = {}

    for module_name in sorted(old_modules):
        old_module = old_modules.get(module_name, {})
        new_module = new_modules.get(module_name)
        old_methods = old_module.get("methods", {}) if isinstance(old_module, dict) else {}
        new_methods = (
            new_module.get("methods", {})
            if isinstance(new_module, dict)
            else {}
        )

        if new_module is None:
            problems.append(f"module removed: {module_name}")

        for method_name in sorted(old_methods):
            old_method = old_methods[method_name]
            new_method = new_methods.get(method_name)

            if new_method is None:
                problems.append(f"method removed: {module_name}.{method_name}")
                continue

            if not isinstance(old_method, dict) or not isinstance(new_method, dict):
                if old_method != new_method:
                    problems.append(f"method changed: {module_name}.{method_name}")
                continue

            if old_method.get("async") != new_method.get("async"):
                problems.append(f"async behaviour changed: {module_name}.{method_name}")

            old_shape = _shape(old_method.get("return_value"))
            new_shape = _shape(new_method.get("return_value"))
            if old_shape != new_shape:
                problems.append(
                    f"return shape changed: {module_name}.{method_name} "
                    f"({old_shape} -> {new_shape})"
                )

        for method_name in sorted(new_methods):
            if method_name not in old_methods:
                problems.append(f"method added: {module_name}.{method_name}")

    for module_name in sorted(new_modules):
        if module_name not in old_modules:
            problems.append(f"module added: {module_name}")

    old_schemas = old.get("nested_schemas", {})
    new_schemas = new.get("nested_schemas", {})
    if not isinstance(old_schemas, dict):
        old_schemas = {}
    if not isinstance(new_schemas, dict):
        new_schemas = {}

    for schema_name in sorted(old_schemas):
        old_schema = old_schemas[schema_name]
        new_schema = new_schemas.get(schema_name)

        if new_schema is None:
            problems.append(f"schema removed: {schema_name}")
            continue

        if not isinstance(old_schema, dict) or not isinstance(new_schema, dict):
            if old_schema != new_schema:
                problems.append(f"schema changed: {schema_name}")
            continue

        old_fields = set(old_schema) - {"__type__"}
        new_fields = set(new_schema) - {"__type__"}

        added = sorted(new_fields - old_fields)
        removed = sorted(old_fields - new_fields)
        if added:
            problems.append(f"fields added: {schema_name} ({', '.join(added)})")
        if removed:
            problems.append(f"fields removed: {schema_name} ({', '.join(removed)})")

        for field_name in sorted(old_fields & new_fields):
            if old_schema[field_name] != new_schema[field_name]:
                problems.append(
                    f"field type changed: {schema_name}.{field_name} "
                    f"({old_schema[field_name]!r} -> {new_schema[field_name]!r})"
                )

    for schema_name in sorted(new_schemas):
        if schema_name not in old_schemas:
            problems.append(f"schema added: {schema_name}")

    return problems

def render_json(report) -> dict:
    """Lines with their status, findings, and the evidence per test: which tests ran each
    changed line, which noticed its mutant, and what each of those tests fakes. Tools that
    know what a test is *for* (specdeck's requirements) join on the node ids."""
    from collections.abc import Mapping
    from enum import Enum

    def value(item, name, default=None):
        if isinstance(item, Mapping):
            return item.get(name, default)
        return getattr(item, name, default)

    def json_value(item):
        if isinstance(item, Enum):
            return item.value
        if isinstance(item, Mapping):
            return {str(k): json_value(v) for k, v in item.items()}
        if isinstance(item, (list, tuple, set, frozenset)):
            return [json_value(v) for v in item]
        return item

    def location(item):
        if isinstance(item, tuple) and len(item) == 2:
            return item[0], item[1]
        path = value(item, "path")
        line = value(item, "line")
        if path is not None and line is not None:
            return path, line
        return None

    def members(item):
        if item is None:
            return []
        if isinstance(item, Mapping):
            return list(item)
        if isinstance(item, str):
            return [item]
        try:
            return list(item)
        except TypeError:
            return [item]

    def fake_name(item):
        if not isinstance(item, str):
            item = value(item, "name", value(item, "target", item))
        if not isinstance(item, str):
            return str(item)
        return item.rsplit(".", 1)[-1]

    line_keys = list(report.lines)
    line_set = set(line_keys)
    ran_by = {key: set() for key in line_keys}
    killed_by = {key: set() for key in line_keys}
    test_fakes = {}
    test_records = {}

    def add_test(nodeid, record):
        if nodeid is None:
            return
        nodeid = str(nodeid)
        test_records[nodeid] = record
        fakes = value(record, "fakes", value(record, "mocked", value(record, "mocks", [])))
        if fakes is not None:
            test_fakes.setdefault(nodeid, set()).update(fake_name(f) for f in members(fakes))

        for field, destination in (
            ("ran", ran_by),
            ("ran_lines", ran_by),
            ("runs", ran_by),
            ("executed", ran_by),
            ("covered", ran_by),
            ("killed", killed_by),
            ("killed_lines", killed_by),
            ("noticed", killed_by),
            ("mutants_killed", killed_by),
        ):
            for item in members(value(record, field)):
                key = location(item)
                if key in line_set:
                    destination[key].add(nodeid)

    tests = getattr(report, "tests", {})
    if isinstance(tests, Mapping):
        for nodeid, record in tests.items():
            add_test(value(record, "nodeid", nodeid), record)
    else:
        for record in members(tests):
            add_test(value(record, "nodeid", value(record, "id")), record)

    # Some report producers keep test evidence in a separately named mapping.
    for name in ("test_evidence", "evidence_by_test"):
        evidence = getattr(report, name, {})
        if isinstance(evidence, Mapping):
            for nodeid, record in evidence.items():
                add_test(value(record, "nodeid", nodeid), record)

    def add_line_evidence(source, field, destination):
        if not isinstance(source, Mapping):
            return
        for key, names in source.items():
            loc = location(key)
            if loc not in line_set:
                continue
            for name in members(names):
                nodeid = value(name, "nodeid", name)
                if nodeid is not None:
                    destination[ str(nodeid) ].add(loc) if False else destination[loc].add(str(nodeid))

    for name, destination in (
        ("ran_by", ran_by),
        ("line_runs", ran_by),
        ("killed_by", killed_by),
        ("line_kills", killed_by),
    ):
        add_line_evidence(getattr(report, name, {}), name, destination)

    evidence = getattr(report, "evidence", {})
    if isinstance(evidence, Mapping):
        for key, record in evidence.items():
            loc = location(key)
            if loc not in line_set:
                continue
            for field, destination in (
                ("ran_by", ran_by),
                ("ran", ran_by),
                ("killed_by", killed_by),
                ("killed", killed_by),
                ("noticed_by", killed_by),
            ):
                for nodeid in members(value(record, field)):
                    nodeid = value(nodeid, "nodeid", nodeid)
                    if nodeid is not None:
                        destination[loc].add(str(nodeid))

    for name in ("fakes", "test_fakes", "mocks"):
        fake_map = getattr(report, name, {})
        if isinstance(fake_map, Mapping):
            for nodeid, fakes in fake_map.items():
                test_fakes.setdefault(str(nodeid), set()).update(
                    fake_name(fake) for fake in members(fakes)
                )

    all_tests = set(test_records) | set(test_fakes)
    for names in list(ran_by.values()) + list(killed_by.values()):
        all_tests.update(names)

    lines = []
    for path, line in sorted(line_keys):
        lines.append({
            "path": path,
            "line": line,
            "status": json_value(report.lines[(path, line)]),
            "ran_by": sorted(ran_by[(path, line)]),
            "killed_by": sorted(killed_by[(path, line)]),
        })

    findings = []
    for finding in report.findings:
        entry = {
            "kind": json_value(finding.kind),
            "path": finding.path,
            "line": finding.line,
            "message": finding.message,
        }
        if finding.snippet:
            entry["snippet"] = finding.snippet
        if finding.mutant is not None:
            entry["mutant"] = {
                "original": finding.mutant.original,
                "mutated": finding.mutant.mutated,
            }
        findings.append(entry)

    reach = []
    for (path, line), item in sorted(report.reach.items()):
        reach.append({
            "path": path,
            "line": line,
            "function": item["function"],
            "nearest_test": item["nearest_test"],
            "depth": item["depth"],
        })

    return {
        "lines": lines,
        "tests": [
            {"nodeid": nodeid, "fakes": sorted(test_fakes.get(nodeid, set()))}
            for nodeid in sorted(all_tests)
        ],
        "findings": findings,
        "reach": reach,
    }

def is_arid(source: str, line: int) -> bool:
    """True when `line` of `source` should never be mutated."""
    if line < 1:
        return False

    try:
        tree = ast.parse(source)
    except SyntaxError:
        return False

    def covers(node: ast.AST, number: int) -> bool:
        start = getattr(node, "lineno", None)
        end = getattr(node, "end_lineno", start)
        return start is not None and start <= number <= end

    parents: dict[ast.AST, ast.AST] = {}
    for parent in ast.walk(tree):
        for child in ast.iter_child_nodes(parent):
            parents[child] = parent

    # Everything in a conventional main guard is deliberately excluded,
    # including the guard itself.
    for node in ast.walk(tree):
        if covers(node, line) and _in_main_guard(node, parents):
            return True

    # A function signature is arid except for lines occupied by a default
    # value.  Do not classify one-line functions as arid: their header and
    # executable body share a line.
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue

        body_lines = [getattr(statement, "lineno", None) for statement in node.body]
        body_lines = [number for number in body_lines if number is not None]
        if not body_lines:
            continue

        header_end = min(body_lines) - 1
        if not (node.lineno <= line <= header_end):
            continue

        defaults = [
            *node.args.defaults,
            *(default for default in node.args.kw_defaults if default is not None),
        ]
        if any(covers(default, line) for default in defaults):
            return False
        return True

    # Only the first string expression in a module, class, or function body
    # is a docstring.
    docstrings: set[ast.AST] = set()
    for node in ast.walk(tree):
        if not isinstance(node, (ast.Module, ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        if node.body:
            first = node.body[0]
            if (
                isinstance(first, ast.Expr)
                and isinstance(first.value, ast.Constant)
                and isinstance(first.value.value, str)
            ):
                docstrings.add(first)

    for node in docstrings:
        if covers(node, line):
            return True

    for node in ast.walk(tree):
        if not covers(node, line):
            continue
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            return True
        if isinstance(node, ast.AnnAssign) and node.value is None:
            return True
        if isinstance(node, ast.Call) and _is_noise_call(node):
            return True

    return False

def exit_code(report, gate: bool = True) -> int:
    """Return 1 when gating is enabled and the report contains a gate failure.

    Surviving mutants, unrun changed lines, weakened tests, checker tampering,
    changed requirements, and tests contradicting requirements fail the gate.
    Other findings are advisory.
    """
    if not gate:
        return 0
    if any(status == LineStatus.NEVER_RAN for status in report.lines.values()):
        return 1
    return int(any(finding.kind in GATING for finding in report.findings))

def faked(repo, nodeid: str) -> list:
    """Names this test replaces with fakes; [] if it uses none."""
    nodeid = re.sub(r"\[.*\]$", "", nodeid)
    relpath, sep, name = nodeid.partition("::")
    if not sep:
        return []

    path = Path(repo) / relpath
    try:
        function = _functions(str(path), path.stat().st_mtime).get(name)
    except OSError:
        return []

    if function is None:
        return []

    return [
        target
        for node in ast.walk(function)
        if isinstance(node, ast.Call)
        and _name(node) in _PATCHERS
        and (target := _target(node)) is not None
    ]

def select(candidates: dict, cap_per_file: int = 7) -> list:
    """At most one mutant per line (its first, most useful candidate), at most `cap_per_file` per file.

    `candidates`: {path: {line: [Mutant, ...]}}. Lines are taken top to bottom.
    """
    selected = []

    for _path, by_line in candidates.items():
        taken = 0
        for line in sorted(by_line):
            if taken >= cap_per_file:
                break
            line_candidates = by_line[line]
            if not line_candidates:
                continue
            selected.append(line_candidates[0])
            taken += 1

    return selected

def exit_code(model: dict, *, fail_on_failing=False, fail_on_unmet=False, fail_on_untrusted=False) -> int:
    """Return an exit status for a results model, optionally treating failing checks, unmet requirements, or untrusted items as errors. Returns 1 when an enabled failure condition is present, otherwise 0."""
    if fail_on_failing and any(model.get("counts", {}).get(status, 0) for status in BAD):
        return 1

    if fail_on_unmet:
        requirements = model.get("requirements")
        if requirements:
            counts = requirements.get("counts", {})
            if counts.get("total", 0) > counts.get("met", 0):
                return 1
            if any(r.get("status") != "met" for r in requirements.get("requirements", [])):
                return 1

    if fail_on_untrusted:
        trust = model.get("trust")
        if trust and any(
            requirement.get("status") == "met"
            and requirement.get("verdict") in {"unproven", "mock-only"}
            for requirement in trust.get("requirements", [])
        ):
            return 1

    return 0

def stop(self) -> dict:
    """``{nodeid: {(abs path, line)}}``, import-time lines removed."""
    cov = self._cov
    if cov is None:
        return {}

    self._cov = None
    cov.stop()
    data = cov.get_data()

    imported: set = set()
    per_test: dict = {}

    for filename in data.measured_files():
        path = str(Path(filename).resolve())
        for line, contexts in data.contexts_by_lineno(filename).items():
            place = (path, line)
            if IMPORT_CONTEXT in contexts:
                imported.add(place)
            for context in contexts:
                if context and context != IMPORT_CONTEXT:
                    per_test.setdefault(context, set()).add(place)

    for lines in per_test.values():
        lines.difference_update(imported)

    return per_test

def watch(root: Path, pytest_args: list, *, interval: float = 0.6, live: bool = True,
          runner=None, once: bool = False) -> int:
    """Run the suite, then re-run it whenever a watched file changes.

    `runner` is injectable so tests drive this without spawning pytest.
    """
    if runner is None:
        runner = subprocess.call

    command = [sys.executable, "-m", "pytest", *pytest_args]
    if live and "--specdeck-live" not in command:
        command.append("--specdeck-live")

    state = snapshot(root)
    result = runner(command)

    if once:
        return result

    try:
        while True:
            time.sleep(interval)
            current = snapshot(root)
            if changed(state, current):
                state = current
                result = runner(command)
    except KeyboardInterrupt:
        return result

def validate_requirements_file(path) -> list:
    """Diagnostics for a hand-written requirements file.

    ``requirements.load`` already collects its own problems rather than raising;
    this turns them into the same Diagnostic shape so one command reports both.
    """
    from . import requirements

    p = Path(path)
    try:
        text = p.read_text(encoding="utf-8")
    except FileNotFoundError:
        return [Diagnostic("error", "NO_FILE", f"Requirements file does not exist: {p}")]
    except OSError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE",
                           f"Cannot read requirements file {p}: {e}")]

    try:
        yaml.safe_load(text)
    except yaml.YAMLError as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE",
                           f"Cannot parse requirements file {p}: {e}")]

    try:
        result = requirements.load(p)
    except Exception as e:
        return [Diagnostic("error", "REQUIREMENTS_UNREADABLE",
                           f"Cannot load requirements file {p}: {e}")]

    if isinstance(result, tuple) and len(result) == 2:
        _, problems = result
    else:
        problems = getattr(result, "problems", getattr(result, "errors", []))

    if problems is None:
        problems = []
    elif isinstance(problems, str):
        problems = [problems]

    return [
        Diagnostic("error", "REQUIREMENT", str(problem), path=str(p))
        for problem in problems
    ]

def build(spec: dict, requirements: Optional[dict] = None, proofdeck: Optional[dict] = None) -> dict:
    """Builds a feature report from a specification, optionally incorporating requirements and proof-deck data. Returns summary counts, frontier and blocked scenarios, the supplied requirements, trust information, and proof-deck change-status counts."""
    scenarios = scenarios_from_spec(spec)
    by_id = {scenario["id"]: scenario for scenario in scenarios}

    counts = {status: 0 for status in STATUS_ORDER}
    for scenario in scenarios:
        status = scenario["status"]
        if status not in counts:
            status = scenario["status"] = "notrun"
        counts[status] += 1
    counts["total"] = len(scenarios)

    bad = set(BAD)

    def known_dependencies(scenario: dict) -> list:
        return [by_id[dependency] for dependency in scenario["depends_on"] if dependency in by_id]

    frontier = []
    frontier_ids = set()
    for scenario in scenarios:
        if scenario["status"] in bad and all(
            dependency["status"] == "passed" for dependency in known_dependencies(scenario)
        ):
            frontier.append(dict(scenario))
            frontier_ids.add(scenario["id"])

    def root_causes(scenario_id: str, seen: Optional[set] = None) -> list:
        if seen is None:
            seen = set()
        if scenario_id in seen or scenario_id not in by_id:
            return []

        seen = seen | {scenario_id}
        scenario = by_id[scenario_id]
        dependencies = [
            dependency for dependency in known_dependencies(scenario)
            if dependency["status"] in bad or dependency["status"] == "blocked"
        ]

        if scenario_id in frontier_ids:
            return [scenario_id]

        roots = []
        for dependency in dependencies:
            roots.extend(root_causes(dependency["id"], seen))

        if not roots and scenario["status"] in bad:
            roots.append(scenario_id)

        unique = []
        for root in roots:
            if root not in unique:
                unique.append(root)
        return unique

    blocked = []
    held_up = {scenario_id: 0 for scenario_id in frontier_ids}
    for scenario in scenarios:
        if scenario["status"] != "blocked":
            continue
        roots = root_causes(scenario["id"])
        row = dict(scenario)
        row["blocked_by"] = roots
        blocked.append(row)
        for root in roots:
            if root in held_up:
                held_up[root] += 1

    for scenario in frontier:
        scenario["holding_up"] = held_up[scenario["id"]]

    trust = join(requirements, proofdeck) if requirements is not None and proofdeck is not None else None

    changed = None
    if proofdeck is not None:
        changed = {
            "checked": 0,
            "ran-only": 0,
            "never-ran": 0,
            "mock-only": 0,
            "import-time": 0,
        }
        aliases = {
            "not-run": "never-ran",
            "notrun": "never-ran",
            "unrun": "never-ran",
            "unchecked": "never-ran",
        }
        for line in proofdeck.get("lines", []):
            status = aliases.get(line.get("status"), line.get("status"))
            if status in changed:
                changed[status] += 1
            else:
                changed["never-ran"] += 1

    return {
        "feature": spec.get("feature", ""),
        "counts": counts,
        "frontier": frontier,
        "blocked": blocked,
        "requirements": requirements,
        "trust": trust,
        "changed": changed,
    }

def snapshot(root: Path) -> dict:
    """path -> signature for every watched file under root."""
    files = {}
    for directory, dirs, names in os.walk(root):
        dirs[:] = [name for name in dirs if name not in IGNORE_DIRS]
        for name in names:
            path = Path(directory) / name
            if path.suffix not in WATCH_SUFFIXES:
                continue
            try:
                files[str(path)] = _signature(path)
            except OSError:
                # A file may disappear or become unreadable while walking.
                continue
    return files
